SELECT * FROM business_outbox


    state = #{state}


ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE business_outbox
SET lease_until = DATE_ADD(NOW(3), INTERVAL #{seconds} SECOND)
WHERE id = #{id} AND state = 'SENDING' AND lease_owner = #{leaseOwner}

UPDATE business_outbox
SET state = 'SENT', sent_at = NOW(3), lease_owner = NULL, lease_until = NULL
WHERE id = #{id} AND state = 'SENDING' AND lease_owner = #{leaseOwner}

UPDATE business_outbox
SET attempts = attempts + 1,
    state = IF(attempts + 1 >= #{maxAttempts}, 'REVIEW', 'PENDING'),
    next_attempt_at = DATE_ADD(NOW(3), INTERVAL #{delaySeconds} SECOND),
    lease_owner = NULL, lease_until = NULL, last_error = #{error}
WHERE id = #{id} AND state = 'SENDING' AND lease_owner = #{leaseOwner}

UPDATE business_outbox
SET consume_attempts = consume_attempts + 1, last_error = #{error}
WHERE id = #{id} AND state <> 'DONE'
